#pragma clang diagnostic ignored "-Wmissing-prototypes"

#include <metal_stdlib>
#include <simd/simd.h>

using namespace metal;

struct main0_out
{
    float4 FragColor [[color(0)]];
};

struct main0_in
{
    float2 vTexCoord [[user(locn0)]];
};

static inline __attribute__((always_inline))
float3 gamma(thread const float3& v)
{
    return v * v;
}

fragment main0_out main0(main0_in in [[stage_in]], texture2d<float> Source [[texture(0)]], sampler SourceSmplr [[sampler(0)]])
{
    main0_out out = {};
    float3 param = Source.sample(SourceSmplr, in.vTexCoord).xyz;
    out.FragColor = float4(gamma(param), 1.0);
    return out;
}

